<script setup>
import {ref,onMounted} from 'vue'
import {api} from './api.js'
const props=defineProps({kind:String,token:String,language:String})
const emit=defineEmits(['dirty'])
const form=ref(null),busy=ref(false),error=ref(''),notice=ref('')
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const path=props.kind==='operator'?'/api/owner/operator/settings':'/api/admin/manufacturer/settings'
onMounted(async()=>{try{form.value=(await api(path,{token:props.token})).settings}catch(e){error.value=e.message}})
async function save(){busy.value=true;error.value='';notice.value='';try{form.value=(await api(path,{token:props.token,method:'POST',body:JSON.stringify(form.value)})).settings;emit('dirty',false);notice.value=tr('Сохранено','Saqlandi','Saved')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="card content"><h2>{{kind==='operator'?tr('Оператор этого поста','Ushbu post operatori','Station operator'):tr('Производитель LABRIX · контакты','LABRIX ishlab chiqaruvchi · kontaktlar','LABRIX manufacturer contacts')}}</h2><p v-if="error" class="message error">{{error}}</p><p v-if="notice" class="message success">{{notice}}</p><form v-if="form" @submit.prevent="save" @input="emit('dirty',true)" @change="emit('dirty',true)"><div class="fields"><template v-if="kind==='operator'"><label class="check"><input v-model="form.enabled" type="checkbox"/>{{tr('Показывать вызов оператора','Operatorni chaqirish tugmasi','Enable operator calls')}}</label><label>{{tr('Телефон оператора','Operator telefoni','Operator phone')}}<input v-model.trim="form.phone" type="tel" maxlength="40"/></label><label>Telegram chat ID<input v-model.trim="form.chat_id" inputmode="numeric" maxlength="21" placeholder="-100…"/></label><p class="muted">{{tr('Пустой chat ID — вызовы получает привязанный владелец Telegram. Для группы укажите её числовой ID и добавьте бота. Настройка применяется к этому посту. Один вызов в 2 минуты; ожидание отправки — до 5 минут.','Chat ID bo‘sh bo‘lsa, xabar Telegramga ulangan egaga boradi. Guruh uchun uning raqamli ID sini kiriting va botni qo‘shing. Sozlama shu post uchun. Har 2 daqiqada bir chaqiruv.','Leave chat ID empty to notify the paired Telegram owner. For a group, enter its numeric ID and add the bot. Applies to this station; one call per 2 minutes, delivery expires after 5 minutes.')}}</p></template><template v-else><label v-for="[key,ru,uz,en] in [['marketing','Продажи и сотрудничество','Savdo va hamkorlik','Sales and partnerships'],['programmer','Программное обеспечение','Dasturiy ta’minot','Software support'],['electrician','Оборудование и электрика','Uskuna va elektr','Hardware and electrical support']]" :key="key">{{tr(ru,uz,en)}}<input v-model.trim="form[key]" type="tel" maxlength="40"/></label><label v-for="social in ['telegram','instagram','youtube']" :key="social">{{social}} URL<input v-model.trim="form[social]" type="url" maxlength="2048" placeholder="https://"/></label></template></div><button class="primary" style="margin-top:20px" :disabled="busy">{{kind==='operator'?tr('Сохранить оператора','Operatorni saqlash','Save operator'):tr('Сохранить контакты LABRIX','LABRIX kontaktlarini saqlash','Save LABRIX contacts')}}</button></form></section></template>
